  5913	/// DECSTR - Soft Terminal Reset. Resets the modes and state a program may
  5914	/// have left behind, without clearing the screen or moving the cursor.
  5915	/// Beyond what the VT510 manual lists, this also resets what xterm's soft
  5916	/// reset does: left and right margins, the cursor style, the color palette,
  5917	/// modifyOtherKeys, and the XTCHECKSUM variant.
  5918	pub fn softReset(self: *Terminal) void {
  5919	    const reset_modes = [_]modespkg.Mode{
  5920	        .cursor_visible,
  5921	        .insert,
  5922	        .origin,
  5923	        .wraparound,
  5924	        .reverse_wrap,
  5925	        .reverse_wrap_extended,
  5926	        .disable_keyboard,
  5927	        .cursor_keys,
  5928	        .keypad_keys,
  5929	        .enable_left_and_right_margin,
  5930	    };
  5931	    for (reset_modes) |mode| self.modes.set(mode, self.modes.getDefault(mode));
  5932	
  5933	    self.scrolling_region = .{
  5934	        .top = 0,
  5935	        .bottom = self.rows - 1,
  5936	        .left = 0,
  5937	        .right = self.cols - 1,
  5938	    };
  5939	
  5940	    // The default style needs no allocation so this can't fail.
  5941	    const screen: *Screen = self.screens.active;
  5942	    screen.cursor.style = .{};
  5943	    screen.manualStyleUpdate() catch unreachable;
  5944	    screen.cursor.protected = false;
  5945	    // xterm also forgets which protection mode was used last, so erasing
  5946	    // after a soft reset no longer skips ISO (SPA) protected cells.
  5947	    screen.protected_mode = .off;
  5948	    screen.charset = .{};
  5949	
  5950	    // A saved cursor now restores to the home position with the defaults.
  5951	    screen.saved_cursor = null;
  5952	
  5953	    self.status_display = .main;
  5954	    self.flags.modify_other_keys_2 = false;
  5955	    self.flags.xt_checksum = self.default_xt_checksum;
  5956	    self.setCursorStyle(.default);
  5957	
  5958	    // xterm resets the palette for DECSTR as well as RIS, as OSC 104
  5959	    // with no arguments would. Dynamic colors (OSC 10-19) are kept.
  5960	    if (self.colors.palette.mask.count() > 0) {
  5961	        self.colors.palette.resetAll();
  5962	        self.flags.dirty.palette = true;
  5963	    }
  5964	}
